-- name: ReleaseAdvisoryLocks :exec
SELECT pg_advisory_unlock(hashtextextended(lock_key, 0))
FROM unnest(sqlc.arg(lock_keys)::text[]) AS requested(lock_key);

-- name: AcquireAdvisoryLocks :exec
SELECT pg_advisory_lock(hashtextextended(lock_key, 0))
FROM (SELECT DISTINCT unnest(sqlc.arg(lock_keys)::text[]) AS lock_key ORDER BY lock_key) requested;

-- name: GetAlertState :one
SELECT strategy, last_signal_id, last_pushover_at, last_email_at, paused
FROM alert_state WHERE strategy = sqlc.arg('strategy');

-- name: ReleaseOperationalAlert :exec
UPDATE alert_state SET last_pushover_at = NULL
WHERE strategy = sqlc.arg('key') AND last_pushover_at = sqlc.arg('claimed_at');

-- name: PreviousBarClose :one
SELECT close::float8 FROM bars WHERE symbol = sqlc.arg(symbol) AND timeframe = sqlc.arg(timeframe)
  AND ts < sqlc.arg(watermark) ORDER BY ts DESC LIMIT 1;

-- name: BarCloseAtOrBefore :one
SELECT ts, close::float8 FROM bars WHERE symbol = sqlc.arg(symbol) AND timeframe = sqlc.arg(timeframe)
  AND ts <= sqlc.arg(watermark) ORDER BY ts DESC LIMIT 1;

-- name: DeleteBarsSeries :execrows
DELETE FROM bars
WHERE symbol = sqlc.arg(symbol) AND timeframe = sqlc.arg(timeframe);

-- name: DeleteBarSeriesUsage :exec
DELETE FROM bar_series_usage
WHERE symbol = sqlc.arg(symbol) AND timeframe = sqlc.arg(timeframe);

-- name: InsertEquityBorrowSnapshot :one
INSERT INTO equity_borrow_snapshots (
  account_id, symbol, borrow_status, error_code, error_message,
  available_qty, fee_per_share, total_fee, quoted_at, quote_expires_at,
  trading_date, observed_at, source, raw_response
) VALUES (
  sqlc.arg('account_id'), sqlc.arg('symbol'), sqlc.arg('borrow_status'), sqlc.arg('error_code'), sqlc.arg('error_message'), sqlc.arg('available_qty'), sqlc.arg('fee_per_share'), sqlc.arg('total_fee'), sqlc.arg('quoted_at'), sqlc.arg('quote_expires_at'), sqlc.arg('trading_date'), sqlc.arg('observed_at'), sqlc.arg('source'), sqlc.arg('raw_response')
)
RETURNING *;

-- name: InsertExecutionCostEvent :one
INSERT INTO execution_cost_events (
  event_id, source_ref, account_id, symbol, position_cycle_id, intent_id,
  broker_order_id, fill_id, kind, amount, currency, effective_at, raw_response
) VALUES (
  sqlc.arg('event_id'), sqlc.arg('source_ref'), sqlc.arg('account_id'), sqlc.arg('symbol'), sqlc.arg('position_cycle_id'), sqlc.arg('intent_id'), sqlc.arg('broker_order_id'), sqlc.arg('fill_id'), sqlc.arg('kind'), sqlc.arg('amount'), sqlc.arg('currency'), sqlc.arg('effective_at'), sqlc.arg('raw_response')
)
ON CONFLICT (event_id) DO UPDATE SET event_id = EXCLUDED.event_id
RETURNING *;

-- name: DPWebWorkerResolution :one
SELECT selection,activity,resolved_at,observed_at
FROM dynamic_portfolio_resolution_observations WHERE timeframe=sqlc.arg(timeframe);

-- name: DPWebWindows :many
SELECT to_jsonb(w) AS data FROM portfolio_context_window_results w
WHERE w.context_id=sqlc.arg(context_id) ORDER BY w.window_index LIMIT 1001;

-- name: DPWebSymbols :many
SELECT to_jsonb(s) AS data FROM portfolio_symbol_results s
WHERE s.context_id=sqlc.arg(context_id) ORDER BY s.ticker LIMIT 1001;

-- name: DeleteNetworkAttributionCache :exec
DELETE FROM network_attribution_cache
WHERE id = sqlc.arg('id');

-- name: UpdateNotifiedFillTime :exec
UPDATE notified_fills SET last_fill_ts = sqlc.arg('lastFillTs'), updated_at = now()
WHERE key = 'fill' AND last_fill_ts < sqlc.arg('lastFillTs');

-- name: InsertNotifiedFillTime :exec
INSERT INTO notified_fills (last_fill_ts, key) VALUES (sqlc.arg('lastFillTs'), 'fill')
ON CONFLICT DO NOTHING;

-- name: UpsertAlertTime :exec
INSERT INTO notified_fills (last_fill_ts, key) VALUES (sqlc.arg('last_fill_ts'), sqlc.arg('key'))
ON CONFLICT (key) DO UPDATE SET last_fill_ts = EXCLUDED.last_fill_ts, updated_at = now();

-- name: InsertOptimizerSearchEvent :one
INSERT INTO optimizer_search_events (
    asset_class, timeframe, direction, event_type, run_id,
    configuration_id, generation, revision, details
) VALUES (sqlc.arg('asset_class'), sqlc.arg('timeframe'), sqlc.arg('direction'), sqlc.arg('event_type'), sqlc.arg('run_id'), sqlc.arg('configuration_id'), sqlc.arg('generation'), sqlc.arg('revision'), sqlc.arg('details'))
RETURNING *;

-- name: InsertTradebotConfigSelection :one
INSERT INTO tradebot_config_selections (
    configuration_id, asset_class, timeframe, direction,
    source_run_id, effective_from, promotion_reason
) VALUES (sqlc.arg('configuration_id'), sqlc.arg('asset_class'), sqlc.arg('timeframe'), sqlc.arg('direction'), sqlc.arg('source_run_id'), sqlc.arg('effective_from'), sqlc.arg('promotion_reason'))
RETURNING *;

-- name: GetOptimizerScopeState :one
SELECT * FROM optimizer_scope_state
WHERE asset_class = sqlc.arg('asset_class') AND timeframe = sqlc.arg('timeframe') AND direction = sqlc.arg('direction');

-- name: ListOptimizerScopeStates :many
SELECT * FROM optimizer_scope_state
ORDER BY asset_class, timeframe, direction;

-- name: GetOptimizerHistoryBackfill :one
SELECT * FROM optimizer_history_backfills
WHERE asset_class = sqlc.arg('asset_class') AND timeframe = sqlc.arg('timeframe') AND universe_hash = sqlc.arg('universe_hash');

-- name: CreateSignalRun :one
INSERT INTO signal_runs (
    configuration_id, effective_from, range_start, range_end
) VALUES (sqlc.arg('configuration_id'), sqlc.arg('effective_from'), sqlc.arg('range_start'), sqlc.arg('range_end'))
RETURNING *;

-- name: SaveParityCycleAudit :exec
INSERT INTO tradebot_parity_cycle_audits(receipt_id,result) VALUES(sqlc.arg(receipt_id),sqlc.arg(result))
ON CONFLICT DO NOTHING;

-- name: SaveParityExitEvaluation :exec
INSERT INTO tradebot_parity_exit_evaluations (intent_id,identity,inputs)
VALUES ($1,$2,$3) ON CONFLICT DO NOTHING;

-- name: GetParityInputs :many
SELECT input_hash,payload FROM tradebot_parity_inputs
WHERE input_hash=ANY(sqlc.arg('input_hashes')::text[]);

-- name: GetSignalEvaluationFingerprint :one
SELECT canonical_config FROM signal_strategy_config_snapshots
WHERE strategy_config_hash = sqlc.arg('strategy_config_hash');

-- name: ListPresentParityInputs :many
SELECT input_hash FROM tradebot_parity_inputs
WHERE input_hash = ANY(sqlc.arg('input_hashes')::text[]);

-- name: GetParityProtection :one
SELECT * FROM tradebot_parity_protection_captures
WHERE account_id=sqlc.arg(account_id) AND broker=sqlc.arg(broker) AND broker_order_id=sqlc.arg(broker_order_id);

-- name: GetPreparedParityProtection :one
SELECT * FROM tradebot_parity_protection_captures
WHERE account_id=sqlc.arg(account_id) AND broker=sqlc.arg(broker) AND capture_id=sqlc.arg(capture_id);

-- name: InsertDynamicPortfolioChangeNotification :exec
INSERT INTO dynamic_portfolio_change_notifications (
    champion_id, timeframe, added_symbols, removed_symbols, portfolio_symbols
)
VALUES (sqlc.arg('champion_id'), sqlc.arg('timeframe'), sqlc.arg('added_symbols'), sqlc.arg('removed_symbols'), sqlc.arg('portfolio_symbols'))
ON CONFLICT (champion_id) DO NOTHING;

-- name: CurrentMacroRegimeAverages :one
SELECT COALESCE(AVG(soxx_20d_pct), 0)::float8 AS soxx, COALESCE(AVG(vixy_20d_pct), 0)::float8 AS vixy
FROM ticker_backtest_results WHERE strategy LIKE '%_3m_now' AND generation = 1;

-- name: UpsertSignalPortfolioSnapshot :exec
INSERT INTO signal_portfolio_snapshots (
    portfolio_hash, hash_version, timeframe, asset_type,
    tradeable_symbols, context_symbols, canonical_snapshot
) VALUES (sqlc.arg('portfolio_hash'), sqlc.arg('hash_version'), sqlc.arg('timeframe'), sqlc.arg('asset_type'), sqlc.arg('tradeable_symbols'), sqlc.arg('context_symbols'), sqlc.arg('canonical_snapshot'))
ON CONFLICT (portfolio_hash) DO NOTHING;

-- name: UpsertSignalStrategyConfigSnapshot :exec
INSERT INTO signal_strategy_config_snapshots (
    strategy_config_hash, hash_version, strategy_evaluation_version, canonical_config
) VALUES (sqlc.arg('strategy_config_hash'), sqlc.arg('hash_version'), sqlc.arg('strategy_evaluation_version'), sqlc.arg('canonical_config'))
ON CONFLICT (strategy_config_hash) DO NOTHING;

-- name: GetLastEvaluation :one
SELECT evaluated_at FROM signal_evaluations
WHERE strategy_id = sqlc.arg('strategy_id') AND symbol = sqlc.arg('symbol') AND timeframe = sqlc.arg('timeframe');

-- name: MaxDirectionalSignalID :one
SELECT COALESCE(MAX(s.id), 0)::bigint FROM signals s JOIN strategies st ON st.id = s.strategy_id
WHERE st.name = sqlc.arg(strategy) AND s.direction <> 'flat';

-- name: UpsertOptimizerStrategyRankSnapshot :one
INSERT INTO optimizer_strategy_rank_snapshots (
    configuration_id, asset_class, timeframe, direction,
    data_watermark, universe_hash, score_version
) VALUES (sqlc.arg('configuration_id'), sqlc.arg('asset_class'), sqlc.arg('timeframe'), sqlc.arg('direction'), sqlc.arg('data_watermark'), sqlc.arg('universe_hash'), sqlc.arg('score_version'))
ON CONFLICT (
    configuration_id, asset_class, timeframe, direction,
    data_watermark, universe_hash, score_version
) DO UPDATE SET configuration_id = EXCLUDED.configuration_id
RETURNING *;

-- name: TaxHeldBalance :one
SELECT greatest(0, COALESCE(sum(held_delta), 0) - COALESCE(sum(withdrawn_amount), 0))::double precision AS held
FROM tax_liability_events WHERE account_id = sqlc.arg(account_id) AND tax_year = sqlc.arg(tax_year);

-- name: InsertTaxWithdrawal :exec
INSERT INTO tax_liability_events (
    event_id, account_id, tax_year, event_type, source_type, source_id,
    withdrawn_amount, effective_at, rule_version, complete, note
) VALUES (sqlc.arg(event_id), sqlc.arg(account_id), sqlc.arg(tax_year), 'withdrawal', 'cli', sqlc.arg(event_id),
    sqlc.arg(withdrawn_amount), now(), 'operator-withdrawal', true, sqlc.arg(note));

-- name: FreshTaxHistoryReconciliation :one
SELECT EXISTS(SELECT 1 FROM tax_history_reconciliation WHERE account_id = sqlc.arg(account_id)
  AND profile_hash = sqlc.arg(profile_hash) AND checked_through > sqlc.arg(checked_after))::bool;

-- name: TaxReconciliationFillExists :one
SELECT EXISTS (
    SELECT 1 FROM tax_lot_dispositions d WHERE d.account_id = sqlc.arg(account_id) AND d.closing_fill_id = sqlc.arg(fill_id)
    UNION ALL
    SELECT 1 FROM tax_lots l WHERE l.account_id = sqlc.arg(account_id) AND l.source_fill_id = sqlc.arg(fill_id)
) AS exists;

-- name: UpdateTaxLotRemaining :exec
UPDATE tax_lots SET remaining_qty = sqlc.arg(remaining_qty)::text::numeric, updated_at = now()
WHERE lot_id = sqlc.arg(lot_id);

-- name: InsertTaxLot :exec
INSERT INTO tax_lots (
    lot_id, account_id, symbol, asset_class, direction, original_qty,
    remaining_qty, unit_basis, opened_at, source_fill_id, complete, missing_data
) VALUES (
    sqlc.arg(lot_id), sqlc.arg(account_id), sqlc.arg(symbol), sqlc.arg(asset_class), sqlc.arg(direction),
    sqlc.arg(original_qty)::text::numeric, sqlc.arg(remaining_qty)::text::numeric, sqlc.arg(unit_basis)::text::numeric,
    sqlc.arg(opened_at), sqlc.arg(source_fill_id), sqlc.arg(complete), sqlc.arg(missing_data)
) ON CONFLICT (lot_id) DO NOTHING;

-- name: InsertTaxLotDisposition :exec
INSERT INTO tax_lot_dispositions (
    disposition_id, lot_id, account_id, symbol, opening_fill_id, closing_fill_id,
    qty, proceeds, basis, taxable_gain, tax_character, opened_at, closed_at, complete, missing_data
) VALUES (
    sqlc.arg(disposition_id), sqlc.arg(lot_id), sqlc.arg(account_id), sqlc.arg(symbol),
    sqlc.arg(opening_fill_id), sqlc.arg(closing_fill_id), sqlc.arg(qty)::text::numeric,
    sqlc.arg(proceeds)::text::numeric, sqlc.arg(basis)::text::numeric, sqlc.arg(taxable_gain)::text::numeric,
    sqlc.arg(tax_character), sqlc.arg(opened_at), sqlc.arg(closed_at), sqlc.arg(complete), sqlc.arg(missing_data)
) ON CONFLICT (disposition_id) DO NOTHING;

-- name: GetCurrentGeneration :one
SELECT COALESCE(MAX(generation), 0)::int AS generation
FROM ticker_backtest_results;

-- name: CountTickerBacktestResultsForGeneration :one
SELECT COUNT(*) FROM ticker_backtest_results
WHERE generation = sqlc.arg('generation');

-- name: RecordTradebotCyclePhase :exec
INSERT INTO tradebot_cycle_phases(receipt_id, sequence, phase, observed_at, evidence)
VALUES(sqlc.arg(receipt_id), sqlc.arg(sequence), sqlc.arg(phase), sqlc.arg(observed_at), sqlc.arg(evidence));

-- name: UpsertTradebotBrokerActivityCursor :exec
INSERT INTO tradebot_broker_activity_cursors (
  broker, account_id, asset_class, activity_type, last_activity_at
) VALUES (
  sqlc.arg(broker), sqlc.arg(account_id), sqlc.arg(asset_class),
  sqlc.arg(activity_type), sqlc.arg(last_activity_at)
)
ON CONFLICT (broker, account_id, asset_class, activity_type) DO UPDATE SET
  last_activity_at = GREATEST(
    tradebot_broker_activity_cursors.last_activity_at,
    EXCLUDED.last_activity_at
  ),
  updated_at = now();

-- name: MarkTradebotBrokerActivityFetch :exec
INSERT INTO tradebot_broker_activity_cursors (
  broker, account_id, asset_class, activity_type, last_activity_at, last_fetch_at
) VALUES (
  sqlc.arg(broker), sqlc.arg(account_id), sqlc.arg(asset_class),
  sqlc.arg(activity_type), to_timestamp(0), sqlc.arg(fetched_at)
)
ON CONFLICT (broker, account_id, asset_class, activity_type) DO UPDATE SET
  last_fetch_at = EXCLUDED.last_fetch_at,
  updated_at = now();

-- name: GetTradebotInventoryState :one
SELECT * FROM tradebot_inventory_states
WHERE scope_id = sqlc.arg('scope_id') AND symbol = sqlc.arg('symbol');

-- name: SaveTradebotBacktestParityEvidence :exec
INSERT INTO tradebot_backtest_parity_evidence (
  fill_id, evaluation_hash, report_id, matched, result
) VALUES (
  sqlc.arg('fill_id'), sqlc.arg('evaluation_hash'), sqlc.arg('report_id'),
  sqlc.arg('matched'), sqlc.arg('result')::jsonb
)
ON CONFLICT (fill_id, evaluation_hash, report_id) DO UPDATE
SET matched = EXCLUDED.matched, result = EXCLUDED.result, checked_at = now()
WHERE NOT tradebot_backtest_parity_evidence.matched;

-- name: GetParityOrderDecision :one
SELECT result FROM tradebot_parity_order_decisions
WHERE intent_id=sqlc.arg(intent_id) AND evaluation_hash=sqlc.arg(evaluation_hash);

-- name: SaveTradebotSubmittedLimitPrice :exec
UPDATE tradebot_intents SET submitted_limit_price=sqlc.arg(price)::text::numeric
WHERE intent_id=sqlc.arg(intent_id) AND submitted_limit_price IS NULL;

-- name: GetTradebotShortGateProfitLockState :one
SELECT * FROM tradebot_short_gate_profit_lock_states
WHERE scope_id = sqlc.arg('scopeID');

-- name: GetTradebotPortfolioProfitLockState :one
SELECT * FROM tradebot_portfolio_profit_lock_states
WHERE scope_id = sqlc.arg('scopeID');

